var r=`0113-verivorst`;var i=`world-0113`;var n=`EE`;var t=`northern-europe`;var o=4;var s=43;var u={en:`Verivorst`,ua:`Кров'яна ковбаса`};var g={en:`A baked ready-made blood sausage served with a tart berry accompaniment; no raw blood handling is required.`,ua:`Запечена готова кров’яна ковбаса з кислуватим ягідним доповненням; робота із сирою кров’ю не потрібна.`};var l=[{en:`Gently brown the commercially prepared blood sausage in lard without tearing the casing.`,ua:`Обережно підрум’яньте готову кров’яну ковбасу на смальці, не пошкоджуючи оболонку.`,t:[`searing`],m:12,i:[[`blood-sausage`,700,`g`],[`lard`,25,`g`]]},{en:`Transfer to a 190°C oven until fully heated through; do not use raw blood sausage filling without a validated recipe.`,ua:`Перекладіть у духовку при 190°C та повністю прогрійте; не використовуйте сиру кров’яну начинку без перевіреного рецепта.`,t:[`roasting`],m:28,i:[[`sunflower-oil`,20,`ml`]]},{en:`Serve with sauerkraut and briefly warmed lingonberries with sugar.`,ua:`Подавайте з квашеною капустою та коротко прогрітою брусницею із цукром.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lingonberry`,100,`g`],[`white-granulated-sugar`,40,`g`],[`sauerkraut`,260,`g`]]}];var d={slug:r,id:i,country:`EE`,region:t,servings:4,minutes:43,title:u,text:g,steps:l};export{n as country,d as default,i as id,s as minutes,t as region,o as servings,r as slug,l as steps,g as text,u as title};